function taskPresentation(exercise) {
  if (PRESENTATION_CATALOG[exercise.id]) return PRESENTATION_CATALOG[exercise.id];
  const goals={hanging_piece:'Find the attacked, undefended piece',pin:'Find the pinned piece',false_pin:'Is this an actual pin?',attack_convergence:'Find where the attacks meet',knight_fork:'Find the knight fork square',fake_fork:'Is this a safe knight fork?',blocked_line:'Find the blocker'};
  return {goal:goals[exercise.category] || exercise.prompt,fullGoal:exercise.prompt,targetKind:'square',chips:['Your game'],demoId:exercise.responseType==='verdict_and_square'?'verdict':'single'};
}
function interactionFamily(exercise) {
  return exercise.mode==='flash_vision'?'flash':exercise.mode==='before_after'?'before':exercise.traceSteps?'trace':exercise.responseType==='select_set'?'multi':exercise.responseType==='verdict_and_square'?'verdict':'single';
}
